const D = { density:.5, energy:.55, hue:8, speed:1, scale:1, x:.5, y:.5, style:'monochrome', act:'day_arc', seed:0, grit:.6, accent:.7 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const lrp=(a,b,t)=>a+(b-a)*t;

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const style=P.style;
const mono=style==='monochrome', blue=style==='blueprint', riso=style==='riso', noir=style==='noir', xray=style==='xray';
const en=P.energy*(.5+.5*K.intensity);
const act=P.act; // day_arc = one-way raking sweep; pendulum = shadow rocks back and forth

// t0 guard
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

// slab count from density
const nSlab=Math.round(lrp(4,15,clp(P.density,0,1)));

// ---- static concrete buffer (keyed size+style+seed+density+grit) ----
const key=W+'x'+Hh+':'+style+':'+P.seed+':'+nSlab+':'+Math.round(P.grit*4);
if(!S.base||S.key!==key){
  S.key=key;
  const g=createGraphics(W,Hh); g.colorMode(HSB,360,100,100,100); g.noStroke();
  // sky / backdrop
  if(blue){ g.fill(215,64,26); g.rect(0,0,W,Hh); }
  else if(xray){ g.fill(200,60,8); g.rect(0,0,W,Hh); }
  else if(noir){ g.fill(0,0,8); g.rect(0,0,W,Hh); }
  else { // overcast concrete sky
    for(let i=0;i<80;i++){const f=i/79; g.fill(210,lrp(6,3,f),lrp(56,74,f)); g.rect(0,i*Hh/80-1,W,Hh/80+2);} }
  // ground
  const gy=0.82*Hh;
  if(!blue&&!xray){ g.fill(0,0,noir?14:40); g.rect(0,gy,W,Hh-gy); }

  // build slab list (towers rising from ground + cantilever bars)
  const slabs=[];
  for(let i=0;i<nSlab;i++){
    const w=u*(0.08+fr(i*7+1)*0.20);
    const h=Hh*(0.20+fr(i*7+2)*0.55);
    const cx=fr(i*7+3)*W;
    const kind=fr(i*7+4);
    slabs.push({x:cx-w/2,y:gy-h,w,h,tone:0.82+fr(i*7+5)*0.28,cant:kind>0.7});
  }
  slabs.sort((a,b)=>a.tone-b.tone); // far/dark behind
  for(const sb of slabs){
    const baseB = noir?lrp(10,64,fr(sb.x)):lrp(38,66,(sb.tone-0.82)/0.28);
    if(blue){
      g.noFill(); g.stroke(200,30,96,90); g.strokeWeight(Math.max(1,u*0.0016)); g.rect(sb.x,sb.y,sb.w,sb.h);
      // schematic floor lines
      const fl=Math.round(sb.h/(u*0.05));
      for(let k=1;k<fl;k++){const yy=sb.y+sb.h*k/fl; g.line(sb.x,yy,sb.x+sb.w,yy);}
      g.noStroke();
    } else if(xray){
      g.fill(190,70,70,16); g.rect(sb.x,sb.y,sb.w,sb.h);
      g.noFill(); g.stroke(190,50,100,55); g.strokeWeight(1.2); g.rect(sb.x,sb.y,sb.w,sb.h); g.noStroke();
    } else {
      g.fill(riso?210:0, riso?10:0, baseB); g.rect(sb.x,sb.y,sb.w,sb.h);
      // right face darker (form modeling)
      g.fill(0,0,0,noir?46:24); g.rect(sb.x+sb.w*0.62,sb.y,sb.w*0.38,sb.h);
      // top light edge
      g.fill(0,0,100,noir?10:26); g.rect(sb.x,sb.y,sb.w,Math.max(2,sb.h*0.02));
      if(sb.cant){ g.fill(0,0,baseB*0.9); g.rect(sb.x-sb.w*0.5,sb.y+sb.h*0.1,sb.w*0.5,sb.h*0.16);}
    }
  }
  // stipple concrete tooth over everything (skip blueprint)
  if(!blue){
    const gn=Math.round(4200*(0.4+P.grit));
    for(let i=0;i<gn;i++){
      const px=fr(i*3+900)*W, py=fr(i*3+901)*Hh, a=fr(i*3+902);
      g.fill(0,0,a<0.5?100:0, (xray?2:5)*(0.5+P.grit));
      g.rect(px,py,1.5,1.5);
    }
  }
  S.base=g;
}
image(S.base,0,0,W,Hh);

// ---- raking hard shadow sweep (real-time motion floor via K.t) ----
const gy=0.82*Hh;
const period=42; // seconds per sweep
const sweep = act==='pendulum' ? (0.5+0.5*Math.sin(K.t/period*6.2832*P.speed)) : frc(K.t/period*P.speed); // 0..1
const slope=-0.4; // diagonal
const edgeX=lrp(-0.25,1.25,sweep)*W;
const shA=(noir?52:34)*(0.6+en*0.9);
noStroke();
if(!blue){
  // shadow = region left of the diagonal hard edge, over the built forms
  fill(210,noir?0:20,noir?0:8, shA);
  beginShape();
  vertex(0,0); vertex(edgeX+slope*0,0); vertex(edgeX+slope*Hh,Hh); vertex(0,Hh);
  endShape(CLOSE);
  // bright raking counter-light band just right of edge
  blendMode(ADD);
  fill(46,noir?0:30,100, (10+en*14));
  const bw=u*0.05;
  beginShape();
  vertex(edgeX,0); vertex(edgeX+bw,0); vertex(edgeX+bw+slope*Hh,Hh); vertex(edgeX+slope*Hh,Hh);
  endShape(CLOSE);
  blendMode(BLEND);
}

// ---- the one red accent element (pulses on beat + bass) ----
if(!blue&&P.accent>0.02){
  const pump=K.pulse*0.6 + A.bass*0.7 + K.swell*0.2;
  const ax=P.x*W, ah=Hh*0.5*(0.7+P.scale*0.5), aw=u*0.02*(1+P.scale*0.4);
  const ay=gy-ah;
  const aB=clp(70+pump*40,0,100), aS=xray?80:94;
  blendMode(xray?ADD:BLEND);
  noStroke(); fill(md(H,360),aS,aB*P.accent+20);
  rect(ax-aw/2,ay,aw,ah);
  // glow cap
  blendMode(ADD);
  fill(md(H+6,360),70,100,(18+pump*40)*P.accent);
  ellipse(ax,ay,aw*3*(1+pump*0.6),aw*3*(1+pump*0.6));
  blendMode(BLEND);
}

// ---- dust / grain shimmer (subtle real-time) ----
blendMode(ADD); noStroke();
for(let i=0;i<12;i++){
  const dx=frc(fr(i*2+30)+K.t*0.008)*W, dy=frc(fr(i*2+31)-K.t*0.004)*Hh;
  fill(40,10,100, 6+A.treble*20);
  ellipse(dx,dy,u*0.003,u*0.003);
}
blendMode(BLEND);
